using w3.Domain.Interfaces; using w3.Domain.Models; namespace w3.Infrastructure.Repositories; public class InMemoryStudentRepository : IStudentRepository { private readonly List<Student> _students = []; public Student? GetById(int id) => _students.FirstOrDefault(x => x.StudentId == id); public void Save(Student student) { if (GetById(student.StudentId) is null) _students.Add(student); } }
